const RITUALS_BY_ID = Object.fromEntries(
  catalogRituals.map((ritual) => [ritual.id, ritual]),
) as Record<string, Ritual>

export function getRitualById(id: string | null | undefined): Ritual | null {
  if (!id) return null
  return RITUALS_BY_ID[id] ?? null
}

export function listRitualsByRank(rank: Ritual['rank']): Ritual[] {
  return catalogRituals
    .filter((ritual) => ritual.rank === rank)
    .sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'))
}
